/**
 * Upgrading from 0.8.4: the configuration a 0.8.4 build stored (generated by
 * 0.8.4's own config.js, with a theme, shortcuts, segment modes and a colour
 * changed, tests/fixtures/config-0.8.4.json) loads into this build with every
 * value kept, the settings added since then read their defaults, and the next
 * write keeps the user's values. Every value the fixture holds for a choice
 * setting is one this build still offers, so no binding is reset.
 *
 * Run: node tests/unit/upgrade-from-084-test.cjs
 */
const fs = require('fs');
const path = require('path');
const { createReport } = require('../harness/report.cjs');
const { CORE } = require('../harness/stubs.cjs');
const { loadSources } = require('../harness/sandbox.cjs');

const report = createReport();
const t = report.check;

const stored084 = JSON.parse(
  fs.readFileSync(path.join(__dirname, '..', 'fixtures', 'config-0.8.4.json'), 'utf8')
);

const store = new Map([['ytaf-configuration', JSON.stringify(stored084)]]);
const listeners = {};
const storage = new Proxy(
  {
    getItem: (k) => (store.has(k) ? store.get(k) : null),
    setItem: (k, v) => store.set(k, String(v))
  },
  {
    set(target, key, value) {
      store.set(String(key), String(value));
      return true;
    },
    get(target, key) {
      if (key in target) return target[key];
      return store.has(String(key)) ? store.get(String(key)) : undefined;
    }
  }
);
const { sandbox, get } = loadSources(['text.js', 'config-options.js', 'config.js'].map(CORE), {
  setTimeout: (cb) => setTimeout(cb, 0),
  clearTimeout,
  JSON,
  Map,
  Set,
  Object,
  Array,
  Error,
  String,
  createLogger: () => ({ debug() {}, info() {}, warn() {}, error() {} }),
  localStorage: storage,
  window: {
    localStorage: storage,
    addEventListener(type, fn) {
      (listeners[type] = listeners[type] || []).push(fn);
    }
  }
});
const options = get('configOptions');

const lost = Object.keys(stored084).filter((k) => !options.has(k));
t('every setting 0.8.4 stored still exists', lost.length === 0, lost.join(', '));

const changed = Object.keys(stored084).filter(
  (k) => options.has(k) && sandbox.configRead(k) !== stored084[k]
);
t(
  'every stored value reads back as 0.8.4 left it',
  changed.length === 0,
  changed.map((k) => `${k}: ${stored084[k]} -> ${sandbox.configRead(k)}`).join('; ')
);

t(
  "the user's non-default choices survive (a sample)",
  sandbox.configRead('uiTheme') === 'classic-red' &&
    sandbox.configRead('thumbnailQualityMode') === 'eager' &&
    sandbox.configRead('shortcut_key_3') === 'toggle_subs' &&
    sandbox.configRead('shortcut_key_red') === 'none' &&
    sandbox.configRead('sbMode_sponsor') === 'manual_skip' &&
    sandbox.configRead('sponsorColor') === '#123456' &&
    sandbox.configRead('forceVideoCodec') === 'no_av1' &&
    sandbox.configRead('videoShelfOpacity') === 65
);

const added = [...options.keys()].filter((k) => !(k in stored084));
t(
  'the settings added since 0.8.4 read their defaults',
  added.length > 0 && added.every((k) => sandbox.configRead(k) === sandbox.configGetDefault(k)),
  added.join(', ')
);
t('Load Rows Ahead is on for an upgraded user', sandbox.configRead('enableRowsAhead') === true);

// The choice settings: each stored value is one this build offers.
const choices = {
  thumbnailQualityMode: get('thumbnailQualityModes'),
  forceVideoCodec: get('videoCodecModes'),
  logoStyle: get('logoStyles'),
  forcePreviews: get('forcePreviewModes'),
  uiTheme: get('uiThemes')
};
for (const k of Object.keys(stored084)) {
  if (k.startsWith('shortcut_key_')) choices[k] = get('shortcutActions');
  else if (k === 'sbMode_highlight') choices[k] = get('sbModesHighlight');
  else if (k.startsWith('sbMode_')) choices[k] = get('sbModes');
}
const unknown = Object.entries(choices)
  .filter(([k, table]) => !(stored084[k] in table))
  .map(([k]) => `${k}=${stored084[k]}`);
t('every stored choice is one this build offers', unknown.length === 0, unknown.join(', '));

// A change through the panel writes the whole configuration back.
sandbox.configWrite('enableRowsAhead', false);
for (const fn of listeners.pagehide || []) fn();
const written = JSON.parse(store.get('ytaf-configuration'));
const dropped = Object.keys(stored084).filter((k) => written[k] !== stored084[k]);
t(
  'the next write keeps every 0.8.4 value and adds the new one',
  dropped.length === 0 && written.enableRowsAhead === false,
  dropped.join(', ')
);

report.finish();
